import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { toast } from "react-toastify";

const SellerApplyForReels = ({ onClose }) => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    firstName: "",
    lastName: "",
    email: "",
    mobile: "",
    companyName: "",
    companyWebsite: "",
    instagramHandle: "",
    facebookPage: "",
    experience: "",
    categories: "",
    message: ""
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState(false);

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    // Validate form
    if (!formData.firstName) {
      setError("First name is required");
      return;
    }
    
    if (!formData.lastName) {
      setError("Last name is required");
      return;
    }
    
    if (!formData.email) {
      setError("Email is required");
      return;
    }
    
    if (!formData.mobile) {
      setError("Mobile number is required");
      return;
    }
    
    if (!formData.companyName) {
      setError("Company name is required");
      return;
    }
    
    if (!formData.experience) {
      setError("Experience is required");
      return;
    }
    
    if (!formData.categories) {
      setError("Product categories are required");
      return;
    }
    
    setLoading(true);
    setError("");
    
    try {
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 1000));
      setSuccess(true);
      toast.success("Application submitted successfully! We'll contact you soon.");
      
      // Instead of redirecting to a standalone page, close the modal and show login
      // Wait 3 seconds then switch to login view within the same modal
      setTimeout(() => {
        if (onClose) {
          // If we have an onClose function, call it to close the modal
          onClose();
          // Then open the login modal
          window.dispatchEvent(new CustomEvent('openLoginModal', { detail: 'seller-login' }));
        } else {
          // If no onClose function, we're likely on a standalone page, so redirect
          navigate("/studio?message=pending_approval");
        }
      }, 3000);
    } catch (error) {
      setError("Application failed. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="container-fluid">
      <div className="row justify-content-center">
        <div className="col-12">
          {error && (
            <div className="alert alert-danger alert-dismissible fade show" role="alert">
              {error}
              <button 
                type="button" 
                className="btn-close" 
                data-bs-dismiss="alert" 
                aria-label="Close"
                onClick={() => setError("")}
              ></button>
            </div>
          )}
          
          {success && (
            <div className="alert alert-success alert-dismissible fade show" role="alert">
              Application successful! Redirecting to login page...
              <button 
                type="button" 
                className="btn-close" 
                data-bs-dismiss="alert" 
                aria-label="Close"
                onClick={() => setSuccess(false)}
              ></button>
            </div>
          )}
          
          <form onSubmit={handleSubmit} className="mt-3">
            <div className="mb-3">
              <label htmlFor="firstName" className="form-label">
                <i className="fas fa-user me-2"></i>First Name *
              </label>
              <input
                type="text"
                className="form-control form-control-lg rounded"
                id="firstName"
                name="firstName"
                value={formData.firstName}
                onChange={handleChange}
                required
                placeholder="Enter your first name"
              />
            </div>
            
            <div className="mb-3">
              <label htmlFor="lastName" className="form-label">
                <i className="fas fa-user me-2"></i>Last Name *
              </label>
              <input
                type="text"
                className="form-control form-control-lg rounded"
                id="lastName"
                name="lastName"
                value={formData.lastName}
                onChange={handleChange}
                required
                placeholder="Enter your last name"
              />
            </div>
            
            <div className="mb-3">
              <label htmlFor="email" className="form-label">
                <i className="fas fa-envelope me-2"></i>Email Address *
              </label>
              <input
                type="email"
                className="form-control form-control-lg rounded"
                id="email"
                name="email"
                value={formData.email}
                onChange={handleChange}
                required
                placeholder="Enter your email"
              />
            </div>
            
            <div className="mb-3">
              <label htmlFor="mobile" className="form-label">
                <i className="fas fa-mobile-alt me-2"></i>Mobile Number *
              </label>
              <input
                type="tel"
                className="form-control form-control-lg rounded"
                id="mobile"
                name="mobile"
                value={formData.mobile}
                onChange={handleChange}
                required
                placeholder="Enter your mobile number"
              />
            </div>
            
            <div className="mb-3">
              <label htmlFor="companyName" className="form-label">
                <i className="fas fa-building me-2"></i>Company Name *
              </label>
              <input
                type="text"
                className="form-control form-control-lg rounded"
                id="companyName"
                name="companyName"
                value={formData.companyName}
                onChange={handleChange}
                required
                placeholder="Enter your company name"
              />
            </div>
            
            <div className="mb-3">
              <label htmlFor="companyWebsite" className="form-label">
                <i className="fas fa-globe me-2"></i>Company Website
              </label>
              <input
                type="url"
                className="form-control form-control-lg rounded"
                id="companyWebsite"
                name="companyWebsite"
                value={formData.companyWebsite}
                onChange={handleChange}
                placeholder="https://example.com"
              />
            </div>
            
            <div className="mb-3">
              <label htmlFor="instagramHandle" className="form-label">
                <i className="fab fa-instagram me-2"></i>Instagram Handle
              </label>
              <input
                type="text"
                className="form-control form-control-lg rounded"
                id="instagramHandle"
                name="instagramHandle"
                value={formData.instagramHandle}
                onChange={handleChange}
                placeholder="@username"
              />
            </div>
            
            <div className="mb-3">
              <label htmlFor="facebookPage" className="form-label">
                <i className="fab fa-facebook me-2"></i>Facebook Page
              </label>
              <input
                type="text"
                className="form-control form-control-lg rounded"
                id="facebookPage"
                name="facebookPage"
                value={formData.facebookPage}
                onChange={handleChange}
                placeholder="https://facebook.com/page"
              />
            </div>
            
            <div className="mb-3">
              <label htmlFor="experience" className="form-label">
                <i className="fas fa-briefcase me-2"></i>Years of Experience *
              </label>
              <select
                className="form-select form-select-lg rounded"
                id="experience"
                name="experience"
                value={formData.experience}
                onChange={handleChange}
                required
              >
                <option value="">Select experience</option>
                <option value="0-1">0-1 years</option>
                <option value="1-3">1-3 years</option>
                <option value="3-5">3-5 years</option>
                <option value="5+">5+ years</option>
              </select>
            </div>
            
            <div className="mb-3">
              <label htmlFor="categories" className="form-label">
                <i className="fas fa-tags me-2"></i>Product Categories *
              </label>
              <input
                type="text"
                className="form-control form-control-lg rounded"
                id="categories"
                name="categories"
                value={formData.categories}
                onChange={handleChange}
                required
                placeholder="e.g., Electronics, Fashion, Home Decor"
              />
            </div>
            
            <div className="mb-4">
              <label htmlFor="message" className="form-label">
                <i className="fas fa-comment me-2"></i>Why do you want to join our platform?
              </label>
              <textarea
                className="form-control form-control-lg rounded"
                id="message"
                name="message"
                rows="4"
                placeholder="Tell us about your business and goals"
                value={formData.message}
                onChange={handleChange}
              ></textarea>
            </div>

            <div className="d-flex justify-content-between">
              <button
                type="button"
                className="btn btn-outline-secondary"
                onClick={onClose}
                disabled={loading}
              >
                Cancel
              </button>
              <button
                className="btn btn-primary d-flex align-items-center justify-content-center gap-1 fw-medium"
                type="submit"
                disabled={loading}
              >
                {loading ? (
                  <>
                    <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                    Submitting...
                  </>
                ) : (
                  <>
                    <i className="fas fa-paper-plane me-2"></i>Submit Application
                  </>
                )}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default SellerApplyForReels;
